    private static void functional(Domain a,Domain b,Input large,List<Map<String,Object>> setups,List<Map<String,Object>> rows,List<Map<String,Object>> closes)throws Throwable {
        var smallMembers=new LinkedHashMap<>(large.state().members());assertNotNull(smallMembers.remove("opaque_unconsumed_extension"));var small=new OpportunityJson.Obj(smallMembers);var changedMembers=new LinkedHashMap<>(small.members());BigInteger speed=OpportunityJson.integer(small.get("speed"),"speed");changedMembers.put("speed",new OpportunityJson.IntegerValue(speed.equals(BigInteger.valueOf(5))?BigInteger.valueOf(4):speed.add(BigInteger.ONE)));var changed=new OpportunityJson.Obj(changedMembers);
        Input original=packet(small,BigInteger.TWO),different=packet(changed,BigInteger.TWO);Side sa=null,sb=null;Throwable branchFailure=null;
        try {sa=a.open("functional-native-regression",setups);sb=b.open("functional-native-regression",setups);
            successPair(sa,sb,original,"first_occurrence",BigInteger.TWO,rows);successPair(sa,sb,original,"equal_DATA_new_occurrence",BigInteger.TWO,rows);successPair(sa,sb,different,"semantic_changed",BigInteger.valueOf(3),rows);successPair(sa,sb,original,"A_B_A_not_old_occurrence",BigInteger.valueOf(4),rows);
            var invalidMembers=new LinkedHashMap<>(small.members());invalidMembers.put("date_raw",new OpportunityJson.Text("not-an-integer"));Input invalid=packet(new OpportunityJson.Obj(invalidMembers),BigInteger.TWO);
            failurePair(sa,sb,invalid.packet(),"valid_wire_date_rejected_no_token","Native state snapshot frame budget exhausted",false,rows);
            for(Side side:List.of(sa,sb)){Object diagnostics=invoke(side.domain.diagnostics,side.transport);Object production=((Optional<?>)get(diagnostics,"production")).orElseThrow();side.domain.ownDiagnostic(production,"Production");assertEquals(BigInteger.ONE,get(production,"rejectedSnapshotCount"));assertEquals(BigInteger.valueOf(5),get(production,"receivedSnapshotCount"));Object rejected=((Optional<?>)get(production,"lastRejectedSnapshot")).orElseThrow();side.domain.ownDiagnostic(rejected,"RejectedSnapshot");Object received=get(rejected,"original");side.domain.ownDiagnostic(received,"ReceivedSnapshot");assertEquals(sha(invalid.packet()),sha(((NativeWire.Bytes)get(received,"originalPacket")).value()));}
            successPair(sa,sb,original,"accepted_after_semantic_reject_preserves_revision",BigInteger.valueOf(4),rows);
            failurePair(sa,sb,packet(small,BigInteger.ONE).packet(),"native_revision_regression_terminal","Native revision regressed in one connection",true,rows);
        } catch(Throwable failure){branchFailure=failure;throw failure;} finally {closeBoth(sa,sb,closes,branchFailure);}
        closedPair(sa,sb,"close_after_state_and_terminal",rows);
        sa=null;sb=null;branchFailure=null;
        try {sa=a.open("functional-second-HELLO",setups);sb=b.open("functional-second-HELLO",setups);failurePair(sa,sb,NativeWire.packet(HELLO.getBytes(java.nio.charset.StandardCharsets.UTF_8)),"second_HELLO_terminal","a second Native hello invalidates the held session; no automatic reconnect",true,rows);}
        catch(Throwable failure){branchFailure=failure;throw failure;} finally {closeBoth(sa,sb,closes,branchFailure);}
        closedPair(sa,sb,"close_after_second_HELLO",rows);
    }
