            assertEquals(length,scalarLength(value,row));assertArrayEquals(expected,defensiveValue(value,row));if(length>0)input[0]^=0x7f;
            assertEquals(length,scalarLength(value,row));byte[] firstCopy=defensiveValue(value,row);assertArrayEquals(expected,firstCopy);if(length>0)firstCopy[length-1]^=0x55;
